    }
}

project.solution:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int units = sc.nextInt();
        double bill = units * 6.5 + 50;
        System.out.println("Units: " + units);
        System.out.println("Bill: Rs " + bill);
    }
}
